target.css:
:root {
  --cover-bg: #2a4a3e;
  --cover-border: #c8a84b;
  --cover-inner: #1d3530;
  --label-bg: #c8a84b;
  --label-text: #1d3530;
  --title-color: #e8d9a0;
  --divider-color: #c8a84b;
  --meta-key: #a0c4b0;
  --meta-val: #e8d9a0;
  --dots-color: #4a7a62;
  --badge-bg: #1d3530;
  --badge-text: #c8a84b;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
}

.journal-cover {
  background-color: var(--cover-bg);
  border: 4px solid var(--cover-border);
  outline: 2px solid var(--cover-inner);
  outline-offset: -10px;
  border-radius: 4px;
  padding: 24px 28px 20px;
  width: 300px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.journal-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.journal-label {
  background-color: var(--label-bg);
  color: var(--label-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: 2px;
}

.journal-title {
  color: var(--title-color);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-align: center;
  margin: 0;
  line-height: 1.2;
}

.journal-divider {
  height: 2px;
  background-color: var(--divider-color);
  border-radius: 1px;
  opacity: 0.6;
}

.journal-meta {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.meta-row {
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.meta-key {
  color: var(--meta-key);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
}

.meta-dots {
  flex: 1;
  border-bottom: 1px dotted var(--dots-color);
  margin-bottom: 3px;
}

.meta-val {
  color: var(--meta-val);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
}

.journal-footer {
  display: flex;
  justify-content: center;
  margin-top: 4px;
}

.journal-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  padding: 4px 12px;
  border: 1px solid var(--divider-color);
  border-radius: 2px;
}

